.hotspot {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-color: var(--color-primary);
  position: absolute;
}
.hotspot:before {
  content: "";
  width: 35px;
  height: 35px;
  position: absolute;
  border-radius: 50%;
  position: absolute;
  top: -3px;
  left: -3px;
  border: 2px solid var(--color-primary);
  animation: anim-ripple 2s infinite;
}
.hotspot:after {
  content: "+";
  font-size: 21px;
  color: white;
  position: relative;
  top: 1px;
  left: 10px;
}
@keyframes anim-ripple {
  from {
    opacity: 1;
    transform: scale3d(0.75, 0.75, 1);
  }
  to {
    opacity: 0;
    transform: scale3d(1.25, 1.25, 1);
  }
}

.hotspot .tooltips {
  visibility: hidden;
  width: 200px;
  background-color: rgba(0, 0, 0, 0.8);
  color: #fff;
  text-align: center;
  padding: 10px;
  border-radius: 6px;
  /* Pozicování bubliny */
  position: absolute;
  z-index: 1;
  bottom: 125%;
  /* Umístění nad hotspotem */
  left: 50%;
  transform: translateX(-50%);
  /* Šipka bubliny */
  opacity: 0;
  transition: opacity 0.3s;
}

.hotspot .tooltips::after {
  content: "";
  position: absolute;
  top: 100%;
  /* Dolní okraj bubliny */
  left: 50%;
  transform: translateX(-50%);
  border-width: 5px;
  border-style: solid;
  border-color: rgba(0, 0, 0, 0.8) transparent transparent transparent;
}

/* Zobrazení bubliny při hoveru */
.tooltips.show {
  visibility: visible;
  opacity: 1;
}
.tooltips.show p {
  color: white;
  font-size: 14px;
}

.availability-value {
  display: none;
}

.hotspot:focus .tooltips {
  visibility: visible;
