}
#lcd-rz .btn.go {width:100%;justify-content:center;height:56px;padding:0;font-size:14px;letter-spacing:.12em;
  color:#fff!important;position:relative;overflow:hidden;
  background:linear-gradient(100deg,#1d6b4a,#2f9c68 42%,#1f7350);
  box-shadow:0 10px 26px rgba(31,115,80,.34),inset 0 1px 0 rgba(255,255,255,.22)
