  background:linear-gradient(180deg,#3f9a44 0%,#2e7d32 55%,#256b29 100%);color:#fff !important;text-decoration:none !important;
  font:900 14px/1.2 "Exo 2","Segoe UI",Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase;box-shadow:0 8px 18px rgba(46,125,50,.28)}
.lcd-lista__btn::after{content:"";width:8px;height:8px;border:solid currentColor;border-width:2px 2px 0 0;transform:rotate(45deg)}
.lcd-lista__btn:focus-visible{outline:2px solid #1b5e20;outline-offset:3px}
