  html.lcd-lista-on{scroll-padding-bottom:90px}
  /* bublina chatu Luxia nad lištou (len bublina, nie otvorený chat — cart.js lcdBublinaMimoTlacidla dáva .lcd-kosik-bublina) */
  html.lcd-lista-on.lcd-kosik-bublina body.in-kosik iframe[title="Luxia chat"]{bottom:calc(80px + env(safe-area-inset-bottom,0px)) !important}
