  body.in-kosik #cart-wrapper table.cart-table tr.removeable:has(.lcd-truck-cart-summary){grid-template-areas:"img meno meno meno" "img . pocet suma"}
  body.in-kosik #cart-wrapper table.cart-table tr.removeable:has(.lcd-truck-cart-summary):has(td.p-quantity input.amount:not([value="1"])){
