/* telefón: karta s okrajom ako ponuka k setu (10 px), nie od kraja po kraj */
@media(max-width:767px){body.in-kosik #cart-wrapper table.cart-table tr.removeable{margin:0 10px 14px}}
/* súčet a pokračovanie: „CELKOM ZA TOVAR“ a suma v jednom riadku */
