body.in-kosik #cart-wrapper .next-step .next-step-back{color:var(--k-mute) !important;background:none !important;border:0 !important;box-shadow:none !important;
  font:normal 600 15px/1.3 var(--k-body) !important;text-transform:none !important;letter-spacing:0 !important}
body.in-kosik #cart-wrapper .next-step .next-step-back .continue-shopping{text-decoration:underline;text-decoration-thickness:1px;
  text-decoration-color:rgba(20,17,12,.28);text-underline-offset:4px}
/* bublina chatu Luxia by prekryla „Pokračovať“ (cart.js lcdBublinaMimoTlacidla) */
