}
body.lcd-1v #product-detail-form .lcd1v-krok.active .lcd1v-ti::after {
  content: "";
  display: block;
  width: 44px;
  height: 3px;
  margin: 14px 0 0;
  border-radius: 2px;
  background: linear-gradient(90deg, #c49b31, #e8c96a);
