    position: fixed; left: 0; right: 0; bottom: 0; z-index: 60;
    display: flex; align-items: center; gap: 12px; box-sizing: border-box;
    padding: 10px 16px calc(10px + env(safe-area-inset-bottom, 0px));
    background: rgba(255, 255, 255, .94); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
    border-top: 1px solid var(--c1v-line); box-shadow: 0 -8px 24px rgba(20, 15, 5, .10);
    transform: translateY(110%); visibility: hidden;
    transition: transform .35s cubic-bezier(.2, .7, .2, 1), visibility 0s linear .35s;
  }
  body.lcd-1v .lcd1v-lista.on {
    transform: none; visibility: visible;
    transition: transform .35s cubic-bezier(.2, .7, .2, 1), visibility 0s;
  }
  /* otvorené menu webu: lišta ustúpi (ako bublina Luxie v LCD-HDR) */
  /* otvorený panel košíka v hlavičke (clona z-index 58): lišta ustúpi tiež */
  body.lcd-1v.navigation-window-visible .lcd1v-lista.on,
  body.lcd-1v.cart-window-visible .lcd1v-lista.on { visibility: hidden; }
  /* koniec stránky (päta) nezostane pod lištou */
  body.lcd-1v.lcd1v-lista-on { padding-bottom: calc(var(--c1v-lista-h) + env(safe-area-inset-bottom, 0px)); }
  /* bublina chatu Luxia (76 × 76, 50 px od spodku) by ležala na tlačidle lišty -> nad lištu; otvorený chat sa nehýbe.
     :not(#…) = váha ID, inak by vyhralo staršie pravidlo body:has(#js-plugin-header.active) … {bottom:72px !important} */
  body.lcd-1v.lcd1v-lista-on.lcd1v-bublina:not(#lcd1v-x) iframe[title="Luxia chat"] {
    bottom: calc(var(--c1v-lista-h) + 8px + env(safe-area-inset-bottom, 0px)) !important;
  }
}
