  background:var(--ground);color:var(--ink);font-family:var(--body);font-size:17px;line-height:1.6;
  -webkit-font-smoothing:antialiased;overflow-x:clip;width:100%;max-width:100%}
#lcd-blog *,#lcd-blog *:before,#lcd-blog *:after{box-sizing:border-box}
