/* tlacidlo — prebije Shoptet .btn */
#lcd-blog .btn{display:inline-flex;align-items:center;justify-content:center;gap:12px;font-family:var(--disp);font-weight:800;
  text-transform:uppercase;letter-spacing:.09em;font-size:13px;line-height:1.2;padding:16px 30px;border-radius:12px;border:0;
  height:auto;min-height:0;width:auto;white-space:normal;text-align:center;text-decoration:none;
  background:linear-gradient(100deg,var(--gold-lo),var(--gold-hi) 48%,var(--gold));color:#17130a;
  position:relative;overflow:hidden;box-shadow:0 10px 30px rgba(140,105,25,.35);transition:transform .25s,box-shadow .25s}
#lcd-blog .btn:before{content:"";position:absolute;top:0;bottom:0;width:38%;left:-45%;pointer-events:none;
  background:linear-gradient(100deg,transparent,rgba(255,255,255,.34),transparent);animation:lbSheen 3.6s ease-in-out 1.2s infinite}
