@keyframes lbSheen{0%{left:-45%}55%{left:120%}100%{left:120%}}

#lcd-blog .zlato{color:#8f7020;background:linear-gradient(100deg,#8a6b1c,#c49b31 42%,#e0bd63 60%,#96751f);
